function processDescription(description) {
  const imgSrcRegex = /<img.*?src="(.*?)"/;
  const imageURL = description.match(imgSrcRegex)?.[1] || '';

  const textRegex = /<img.*?>(.*?)<br/;
  const descriptionText = description.match(textRegex)?.[1]?.trim() || '';

  return { imageURL, descriptionText };
}

const processedItems = items.map(item => {
  const { imageURL, descriptionText } = processDescription(item.json.description);

  return {
    ...item.json,
    imageURL,
    descriptionText
  };
});

return processedItems;
